from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/headers")
async def read_headers(user_agent: str = Header(alias="user_agent")):
    return {"user_agent": user_agent}

client = TestClient(app)

def test_underscore_header_default():
    # Default convert_underscores=True. 
    # Parameter name 'user_agent' (or alias 'user_agent') should look for 'user-agent'.
    # If we send 'user_agent', it should NOT be accepted.
    response = client.get("/headers", headers={"user_agent": "test-value"})
    # Currently, it might be accepted. We want it to be NOT accepted (422 Unprocessable Entity)
    assert response.status_code == 422

def test_underscore_header_explicit_false():
    # convert_underscores=False.
    # Parameter name 'user_agent' should look for 'user_agent'.
    app_false = FastAPI()
    @app_false.get("/headers")
    async def read_headers_false(user_agent: str = Header(alias="user_agent", convert_underscores=False)):
        return {"user_agent": user_agent}

    client_false = TestClient(app_false)
    response = client_false.get("/headers", headers={"user_agent": "test-value"})
    assert response.status_code == 200
    assert response.json() == {"user_agent": "test-value"}

if __name__ == "__main__":
    try:
        test_underscore_header_default()
        print("test_underscore_header_default passed")
