@app.get("/headers")
async def read_headers(my_header: str = Header(alias="my_header")):
    return {"my_header": my_header}

client = TestClient(app)

def test_underscore_header_default():
    # Default convert_underscores=True. 
    # Parameter name "my_header" (or alias "my_header") should look for "my-header".
    # If we send "my_header", it should NOT be accepted.
    response = client.get("/headers", headers={"my_header": "test-value"})
    assert response.status_code == 422

def test_underscore_header_explicit_false():
    # convert_underscores=False.
    # Parameter name "my_header" should look for "my_header".
    app_false = FastAPI()
    @app_false.get("/headers")
    async def read_headers_false(my_header: str = Header(alias="my_header", convert_underscores=False)):
        return {"my_header": my_header}

    client_false = TestClient(app_false)
    response = client_false.get("/headers", headers={"my_header": "test-value"})
    assert response.status_code == 200
    assert response.json() == {"my_header": "test-value"}

